def verify(text, names, root="."):
    """Verify against the BUNDLE'S BYTES — defect 3. Two independent checks."""
    found, declared = unpack(text)
    problems = []
    if len(found) != len(names):
        problems.append("paired %d, packed %d" % (len(found), len(names)))
    if len(declared) != len(names):
        problems.append("declared %d, packed %d (spurious markers)"
                        % (len(declared), len(names)))
    got = dict(found)
    for n in names:
        if n not in got:
            problems.append("missing member " + n); continue
        if got[n] != read_bytes_exact(os.path.join(root, n)):
            problems.append("body differs " + n)
    # the strong check: rebuild the bundle from what came OUT of it.
    rebuilt = JOIN.join(OPEN_FMT.format(name=n) + b + CLOSE_FMT.format(name=n)
                        for n, b in found)
    if rebuilt.encode("utf-8") != text.encode("utf-8"):
        problems.append("re-assembly is not byte-identical to the bundle")
    return problems

